    41  void LibreTinyPWM::update_frequency(float frequency) {
    42    this->frequency_ = frequency;
    43    // force changing the frequency by removing PWM mode
    44    this->pin_->pin_mode(gpio::FLAG_INPUT);
    45    analogWriteResolution(this->bit_depth_);  // NOLINT
    46    analogWriteFrequency(frequency);          // NOLINT
